Create Patient.code:
// Create a Patient resource from a registration form submission.
create(
  // 1) The FHIR resource type (also used as the request path).
  'Patient',
  // 2) The resource body; resourceType is added for you.
  {
    identifier: [
      {
        system: 'http://moh.example.org/fhir/NamingSystem/national-id',
        value: $.data.nationalId,
      },
    ],
    name: [{ use: 'official', family: $.data.lastName, given: [$.data.firstName] }],
    gender: $.data.sex, // 'male' | 'female' | 'other' | 'unknown'
    birthDate: $.data.dateOfBirth, // YYYY-MM-DD
    telecom: [{ system: 'phone', value: $.data.phone, use: 'mobile' }],
  }
);

Create Observation.code:
// Record a body weight measurement for a patient.
create('Observation', {
  status: 'final',
  category: [
    {
      coding: [
        {
          system: 'http://terminology.hl7.org/CodeSystem/observation-category',
          code: 'vital-signs',
        },
      ],
    },
  ],
  // LOINC code for body weight.
  code: { coding: [{ system: 'http://loinc.org', code: '29463-7', display: 'Body weight' }] },
  subject: { reference: `Patient/${$.data.patientId}` },
  effectiveDateTime: $.data.visitDate,
  valueQuantity: { value: $.data.weightKg, unit: 'kg', system: 'http://unitsofmeasure.org', code: 'kg' },
});

Create Immunization.code:
// Record a vaccine dose administered at a clinic.
create('Immunization', {
  status: 'completed',
  // CVX code for the vaccine given (e.g. 20 = DTaP).
  vaccineCode: { coding: [{ system: 'http://hl7.org/fhir/sid/cvx', code: $.data.cvxCode }] },
  patient: { reference: `Patient/${$.data.patientId}` },
  occurrenceDateTime: $.data.dateGiven,
  lotNumber: $.data.lotNumber,
  location: { reference: `Location/${$.data.facilityId}` },
  protocolApplied: [{ doseNumberPositiveInt: $.data.doseNumber }],
});

Create Encounter.code:
// Log an outpatient visit for a patient.
create('Encounter', {
  status: 'finished',
  class: {
    system: 'http://terminology.hl7.org/CodeSystem/v3-ActCode',
    code: 'AMB',
    display: 'ambulatory',
  },
  subject: { reference: `Patient/${$.data.patientId}` },
  period: { start: $.data.checkInTime, end: $.data.checkOutTime },
  serviceProvider: { reference: `Organization/${$.data.facilityId}` },
});

Submit Transaction Bundle.code:
// Create a Patient and an Encounter in one transaction.
// The urn:uuid fullUrl lets the Encounter reference the new Patient.
createTransactionBundle([
  {
    fullUrl: 'urn:uuid:7f1c2d6e-1b2a-4c3d-9e8f-0a1b2c3d4e5f',
    resource: {
      resourceType: 'Patient',
      name: [{ family: $.data.lastName, given: [$.data.firstName] }],
      birthDate: $.data.dateOfBirth,
    },
    request: { method: 'POST', url: 'Patient' },
  },
  {
    resource: {
      resourceType: 'Encounter',
      status: 'finished',
      class: { system: 'http://terminology.hl7.org/CodeSystem/v3-ActCode', code: 'AMB' },
      subject: { reference: 'urn:uuid:7f1c2d6e-1b2a-4c3d-9e8f-0a1b2c3d4e5f' },
    },
    request: { method: 'POST', url: 'Encounter' },
  },
]);

Submit Claim For Adjudication.code:
// Submit a Claim for adjudication via the $submit operation.
post(
  // 1) Path relative to the FHIR base URL.
  'Claim/$submit',
  // 2) The Claim resource.
  {
    resourceType: 'Claim',
    status: 'active',
    type: { coding: [{ system: 'http://terminology.hl7.org/CodeSystem/claim-type', code: 'professional' }] },
    use: 'claim',
    patient: { reference: `Patient/${$.data.patientId}` },
    created: new Date().toISOString(),
    provider: { reference: `Organization/${$.data.facilityId}` },
    priority: { coding: [{ code: 'normal' }] },
    insurance: [{ sequence: 1, focal: true, coverage: { reference: `Coverage/${$.data.coverageId}` } }],
  }
);

Search Patients By Identifier.code:
// Look up a patient by national ID before deciding to create or update.
get('Patient', {
  // FHIR token search: system|value
  identifier: `http://moh.example.org/fhir/NamingSystem/national-id|${$.data.nationalId}`,
  _count: 10,
});

Search Recently Updated Observations.code:
// Fetch observations for a patient updated since the last run.
get('Observation', {
  subject: `Patient/${$.data.patientId}`,
  _lastUpdated: `gt${$.lastSyncTime || '2026-01-01T00:00:00Z'}`,
  _sort: '-_lastUpdated',
  _count: 100,
});

Get Patient Everything.code:
// Fetch everything held about one patient as a Bundle.
get(`Patient/${$.data.patientId}/$everything`, {
  _count: 200,
});

Get Claims With Patients.code:
// List the latest claims, including the patients they reference.
getClaim(
  // 1) Claim id; pass '' to search all claims.
  '',
  // 2) FHIR search parameters.
  { _include: 'Claim:patient', _sort: '-_lastUpdated', _count: 50 }
);

Search Immunizations For Patient.code:
// List a patient's immunization history.
get('Immunization', {
  patient: `Patient/${$.data.patientId}`,
  status: 'completed',
  _sort: 'date',
});
